#nullable enable // autogenerated

using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Projectiles
{
    [AutoBuffDefinition(VanillaBuffNames.Projectile.airSlashDamageUp)]
    public class AirSlashDamageUpBuff : BuffDefinition
    {
        public AirSlashDamageUpBuff(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new FloatModifier(VanillaEntityProps.DAMAGE, NumberOperator.Add, PROP_DAMAGE_UP));
            AddModifier(new Vector3Modifier(EngineEntityProps.DISPLAY_SCALE, NumberOperator.Multiply, PROP_DISPLAY_SCALE));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var damageUp = GetDamageUp(buff);
            var scaleScalar = 1 + damageUp * 0.01f;
            SetDisplayScale(buff, Vector3.one * scaleScalar);
        }
        public static float GetDamageUp(Buff buff) => buff.GetProperty<float>(PROP_DAMAGE_UP);
        public static void SetDamageUp(Buff buff, float value) => buff.SetProperty(PROP_DAMAGE_UP, value);
        public static Vector3 GetDisplayScale(Buff buff) => buff.GetProperty<Vector3>(PROP_DISPLAY_SCALE);
        public static void SetDisplayScale(Buff buff, Vector3 value) => buff.SetProperty(PROP_DISPLAY_SCALE, value);
        public static readonly VanillaBuffPropertyMeta<float> PROP_DAMAGE_UP = new VanillaBuffPropertyMeta<float>("damage_up");
        public static readonly VanillaBuffPropertyMeta<Vector3> PROP_DISPLAY_SCALE = new VanillaBuffPropertyMeta<Vector3>("display_scale", Vector3.one);
    }
}
